"""Pure publication metadata fixture; no native authority or executor."""
import base64, zlib, copy, json, unittest
from weft_path_fixture import fixture_inputs
from weft_path_fixture_request import authored_path_request
RECEIPT=zlib.decompress(base64.b64decode(''))

def fixture_publication():
    roles=['object_current','edge_current','tombstone','whole_source_history']
    tables=[{'name':['spark_catalog','path_fixture',n],'uuid':f'20000000-0000-0000-0000-{i+1:012d}','version':0} for i,n in enumerate(roles)]
    return {'id':'10000000-0000-0000-0000-000000000001','manifestUuid':'10000000-0000-0000-0000-000000000002','tables':tables},{n:['spark_catalog','path_fixture',n] for n in roles}

class FixtureRequestTests(unittest.TestCase):
    def request(self, **changed):
        m,g,r=fixture_inputs();p,a=fixture_publication()
        args=dict(model_bytes=m,graph_bytes=g,development_registry_bytes=r,public_receipt_bytes=RECEIPT,verify_public_receipt=lambda m,g,r:None,publication=p,aliases=a);args.update(changed)
        return authored_path_request('SELECT s.id FROM start s',**args)
    def test_full_mapping_and_snapshot(self):
        p,a=fixture_publication();request=self.request(publication=p,aliases=a);b=json.loads(request['target']['bindingJson'])
        self.assertEqual((len(b['records']),len(b['relationships'])),(4,3))
        self.assertEqual(sum(len(r['properties']) for r in b['records']),7)
        self.assertEqual(b['relationships'][0]['acceptedDefinition']['inverse'],'starts')
        p['tables'][0]['version']=99;self.assertEqual(b['publication']['tables'][0]['version'],0)
    def test_source_drift_before_verifier(self):
        m,g,r=fixture_inputs();calls=[]
        with self.assertRaises(ValueError):self.request(model_bytes=m+b' ',verify_public_receipt=lambda *x:calls.append(x))
        self.assertEqual(calls,[])
    def test_complete_vector_and_isolated_alias(self):
        for role in ('missing','duplicate_uuid','bad_alias','negative_version'):
            p,a=fixture_publication()
            if role=='missing':p['tables'].pop()
            if role=='duplicate_uuid':p['tables'][1]['uuid']=p['tables'][0]['uuid']
            if role=='bad_alias':a['object_current']=['spark_catalog','wrong','object_current']
            if role=='negative_version':p['tables'][0]['version']=-1
            with self.subTest(role=role),self.assertRaises(ValueError):self.request(publication=p,aliases=a)
    def test_receipt_rejection_propagates(self):
        def refused(*args):raise ValueError('Trusted verification refused')
        with self.assertRaises(ValueError):self.request(verify_public_receipt=refused)

    def test_verifier_non_none_is_refusal(self):
        for value in (False, {'error':'refused'}):
            with self.subTest(value=value),self.assertRaises(ValueError):self.request(verify_public_receipt=lambda *args:value)

    def test_receipt_numeric_work_refuses_before_callback(self):
        for token in (b'9'*1000000,b'1.5',b'NaN'):
            calls=[]
            with self.subTest(token=token[:5]),self.assertRaises(ValueError):self.request(public_receipt_bytes=b'{"untrusted":'+token+b'}',verify_public_receipt=lambda *args:calls.append(args))
            self.assertEqual(calls,[])
